'use strict';

/*
  Faculty Practice Frontend Module
  - โมดูลประสบการณ์/ความเชี่ยวชาญ/Faculty Practice
  - จัดการรายการตาม person_code และใช้วันที่แบบเดียวกับส่วนอื่นของ MIS
  - ใช้ร่วมกับ backend/FacultyPractice.gs
*/

